export const desktopUiCss = "@import './theme.css';\n/* Unstoppable Control. App-owned styles may extend these primitives. */\n* { box-sizing: border-box; }\nbody { margin: 0; font: 13px/1.5 -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: var(--bg); color: var(--text); height: 100vh; overflow: hidden; }\nh1, h2, h3, p { margin: 0; }\nbutton, input, select { font: inherit; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\nbutton { cursor: pointer; }\nbutton:disabled { opacity: .5; cursor: not-allowed; }\nbutton:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }\n[hidden] { display: none !important; }\n#app, .layout { height: 100vh; }\n.layout { display: flex; flex-direction: column; overflow: hidden; }\n.app-header { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; min-height: 60px; padding: 12px 20px; border-bottom: 1px solid var(--line); background: var(--sidebar); flex-shrink: 0; }\n.brand-mark { color: var(--accent); border: 1px solid var(--accent); border-radius: 3px; padding: 6px; font: 700 14px/1 ui-monospace, monospace; letter-spacing: -.12em; }\n.app-title { font-size: 16px; font-weight: 650; letter-spacing: -.035em; overflow-wrap: anywhere; }\n.app-subtitle { color: var(--muted); font-size: 11px; }\n.app-header > .mono { margin-left: auto; font-size: 11px; }\n.workspace { display: grid; grid-template-columns: 185px minmax(0, 1fr); flex: 1; min-height: 0; }\n.sidebar { display: flex; flex-direction: column; gap: 24px; min-height: 0; padding: 24px 12px 16px; border-right: 1px solid var(--line); background: var(--sidebar); overflow-y: auto; }\n.sidebar nav { display: grid; gap: 5px; }\n.nav-link { display: flex; align-items: center; gap: 10px; padding: 10px 12px; color: var(--muted); border: 1px solid transparent; border-radius: var(--radius); text-decoration: none; font-size: 12px; }\n.nav-link:hover { color: var(--text); background: var(--surface); }\n.nav-link[aria-current=\"location\"] { color: var(--accent); background: var(--tint); border-color: var(--line); }\n.nav-symbol { width: 16px; text-align: center; font-family: ui-monospace, monospace; flex-shrink: 0; }\n.sidebar-footer { margin-top: auto; padding: 0 12px; font-size: 11px; color: var(--muted); }\n.sidebar-footer p + p { margin-top: 8px; }\n.eyebrow { font-size: 10px; letter-spacing: .09em; text-transform: uppercase; font-weight: 600; color: var(--muted); }\n.content { overflow-y: auto; min-width: 0; padding: 26px 28px; display: flex; flex-direction: column; gap: 20px; scroll-padding-top: 24px; }\n.page-heading h1 { font-size: 25px; font-weight: 600; letter-spacing: -.045em; margin: 4px 0; }\n.page-heading > p:last-child { font-size: 12px; color: var(--muted); }\n.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; min-width: 0; scroll-margin-top: 2px; }\n.card-title { font-size: 14px; font-weight: 600; margin-bottom: 12px; }\n.card-hint { font-size: 12px; color: var(--muted); margin-bottom: 14px; }\n.mono { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\n.row { display: flex; align-items: center; flex-wrap: wrap; }\n.gap-8 { gap: 8px; }\nlabel { display: block; font-size: 12px; color: var(--muted); margin: 10px 0 5px; }\n.inp { width: 100%; min-width: 0; background: var(--bg); border: 1px solid var(--line); border-radius: 5px; padding: 9px 10px; color: var(--text); font-size: 13px; margin-bottom: 10px; }\n.btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; background: var(--accent); color: var(--accent-text); border: 1px solid var(--accent); border-radius: 5px; padding: 8px 12px; font-size: 12px; font-weight: 600; }\n.btn:hover { filter: brightness(1.08); }\n.btn-outline { color: var(--text); background: var(--surface); border-color: var(--line); font-weight: 400; }\n.btn-outline:hover { border-color: var(--accent); background: var(--tint); }\n.btn-send { padding: 8px 14px; }\n.result { margin-top: 10px; font: 12px/1.6 ui-monospace, monospace; color: var(--green); overflow-wrap: anywhere; white-space: pre-wrap; }\n.error { color: var(--red); margin-bottom: 10px; }\n.chat-list { max-height: 320px; overflow-y: auto; margin-bottom: 12px; display: flex; flex-direction: column; gap: 8px; }\n.chat-hint { color: var(--muted); font-size: 13px; text-align: center; padding: 20px; }\n.bubble { border-radius: var(--radius); padding: 10px 12px; max-width: 85%; font-size: 13px; white-space: pre-wrap; overflow-wrap: anywhere; }\n.bubble-user { background: var(--tint); color: var(--text); align-self: flex-end; }\n.bubble-assistant { background: var(--bg); color: var(--text); border: 1px solid var(--line); align-self: flex-start; }\n.link { display: block; color: var(--accent); font-size: 12px; text-decoration: none; margin-bottom: 8px; }\n.link:hover { text-decoration: underline; }\n@media (max-width: 900px) { .workspace { grid-template-columns: 160px minmax(0, 1fr); } .content { padding: 22px; } }\n@media (max-width: 600px) {\n  .workspace { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); }\n  .sidebar { padding: 10px; border-right: 0; border-bottom: 1px solid var(--line); }\n  .sidebar nav { display: flex; flex-wrap: wrap; gap: 4px; }\n  .sidebar-footer, .sidebar > .eyebrow, .nav-symbol { display: none; }\n  .nav-link { padding: 8px; font-size: 11px; }\n  .content { padding: 18px 12px; }\n  .app-header { padding: 10px 12px; gap: 8px; }\n  .app-subtitle { display: none; }\n  .app-header > .mono { width: 100%; margin-left: 0; }\n  .row > .inp { flex-basis: 100% !important; }\n}\n@media (pointer: coarse) { .btn, .nav-link, .inp { min-height: 44px; } .inp { font-size: 16px; } }\n@media (prefers-reduced-motion: no-preference) { .btn, .nav-link { transition: background-color 120ms, border-color 120ms; } }\n"
export const desktopShellSource = "// Navigation enhances real in-page anchors; no feature UI is unmounted.\nexport function setupNavigation() {\n  const links = [...document.querySelectorAll('.sidebar .nav-link')]\n  const content = document.querySelector('main.content')\n  for (const section of document.querySelectorAll('main section[data-testid]')) section.id ||= section.dataset.testid\n  function select(link) {\n    for (const item of links) {\n      if (item === link) item.setAttribute('aria-current', 'location')\n      else item.removeAttribute('aria-current')\n    }\n  }\n  function updateFromScroll() {\n    if (!content) return\n    const bounds = content.getBoundingClientRect()\n    const atEnd = content.scrollTop > 0 && content.scrollTop + content.clientHeight >= content.scrollHeight - 2\n    let current = links[0]\n    for (const link of links) {\n      const section = document.getElementById(link.hash.slice(1))\n      if (section && section.getBoundingClientRect().top <= (atEnd ? bounds.bottom - 1 : bounds.top + 32)) current = link\n    }\n    select(current)\n  }\n  for (const link of links) link.addEventListener('click', () => select(link))\n  content?.addEventListener('scroll', updateFromScroll)\n  updateFromScroll()\n}\n"
